+1|/* Stock market sector-bubble + table visualization (D3 v6). */
+2|
+3|const SECTOR_ORDER = [
+4|    "Information Technology",
+5|    "Financial",
+6|    "Industry",
+7|    "Energy",
+8|    "ETF"
+9|];
+10|
+11|const SECTOR_COLORS = {
+12|    "Information Technology": "#2b7cff",
+13|    "Financial":              "#1e9e6a",
+14|    "Industry":               "#e67e22",
+15|    "Energy":                 "#c0392b",
+16|    "ETF":                    "#8e44ad"
+17|};
+18|
+19|const CHART_WIDTH  = 760;
+20|const CHART_HEIGHT = 620;
+21|
+22|function formatMarketCap(value) {
+23|    if (value == null || isNaN(value) || value === 0) return "—";
+24|    const abs = Math.abs(value);
+25|    if (abs >= 1e12) return (value / 1e12).toFixed(2) + "T";
+26|    if (abs >= 1e9)  return (value / 1e9 ).toFixed(2) + "B";
+27|    if (abs >= 1e6)  return (value / 1e6 ).toFixed(2) + "M";
+28|    if (abs >= 1e3)  return (value / 1e3 ).toFixed(2) + "K";
+29|    return value.toFixed(2);
+30|}
+31|
+32|function sectorCenter(sector, width, height) {
+33|    // Place cluster centers in a compact pattern near the middle of the chart.
+34|    const cx = width  / 2;
+35|    const cy = height / 2;
+36|    const dx = 170;
+37|    const dy = 150;
+38|    const positions = {
+39|        "Information Technology": [cx - dx, cy - dy],
+40|        "Financial":              [cx + dx, cy - dy],
+41|        "Industry":               [cx - dx, cy + dy],
+42|        "Energy":                 [cx + dx, cy + dy],
+43|        "ETF":                    [cx,       cy       ]
+44|    };
+45|    return positions[sector] || [cx, cy];
+46|}
+47|
+48|d3.csv("data/stock-descriptions.csv").then(raw => {
+49|    // Normalize + deterministic sort (by sector, then ticker).
+50|    const stocks = raw.map(r => ({
+51|        ticker:    r.ticker,
+52|        name:      r["full name"],
+53|        sector:    r.sector,
+54|        marketCap: r.marketCap ? +r.marketCap : null,
+55|        country:   r.country || "",
+56|        website:   r.website || "",
+57|        isETF:     r.sector === "ETF"
+58|    }));
+59|
+60|    stocks.sort((a, b) => {
+61|        const sa = SECTOR_ORDER.indexOf(a.sector);
+62|        const sb = SECTOR_ORDER.indexOf(b.sector);
+63|        if (sa !== sb) return sa - sb;
+64|        return d3.ascending(a.ticker, b.ticker);
+65|    });
+66|
+67|    renderBubbleChart(stocks);
+68|    renderTable(stocks);
+69|    renderLegend();
+70|});
+71|
+72|// ---------------- Bubble chart ---------------- //
+73|
+74|function renderBubbleChart(stocks) {
+75|    const width  = CHART_WIDTH;
+76|    const height = CHART_HEIGHT;
+77|
+78|    // Radius scale from market cap. ETFs get a uniform size.
+79|    const mcapExtent = d3.extent(stocks.filter(d => d.marketCap), d => d.marketCap);
+80|    const radiusScale = d3.scaleSqrt()
+81|        .domain(mcapExtent)
+82|        .range([16, 48]);
+83|    const ETF_RADIUS = 22;
+84|
+85|    stocks.forEach(d => {
+86|        d.radius = d.isETF ? ETF_RADIUS : radiusScale(d.marketCap);
+87|        const [cx, cy] = sectorCenter(d.sector, width, height);
+88|        d.targetX = cx;
+89|        d.targetY = cy;
+90|        // Deterministic initial placement at the sector centroid so the
+91|        // force simulation converges to the same layout on every run.
+92|        d.x = cx;
+93|        d.y = cy;
+94|    });
+95|
+96|    const svg = d3.select("#bubble-chart")
+97|        .append("svg")
+98|        .attr("viewBox", `0 0 ${width} ${height}`)
+99|        .attr("preserveAspectRatio", "xMidYMid meet");
+100|
+101|    const sim = d3.forceSimulation(stocks)
+102|        .force("x",       d3.forceX(d => d.targetX).strength(0.14))
+103|        .force("y",       d3.forceY(d => d.targetY).strength(0.14))
+104|        .force("collide", d3.forceCollide(d => d.radius + 1.5).iterations(4))
+105|        .stop();
+106|
+107|    // Run a fixed number of ticks for deterministic output.
+108|    for (let i = 0; i < 400; i++) sim.tick();
+109|
+110|    const node = svg.append("g")
+111|        .attr("class", "bubbles")
+112|        .selectAll("g.bubble-node")
+113|        .data(stocks, d => d.ticker)
+114|        .join("g")
+115|        .attr("class", "bubble-node")
+116|        .attr("data-ticker", d => d.ticker)
+117|        .attr("transform", d => `translate(${d.x},${d.y})`);
+118|
+119|    node.append("circle")
+120|        .attr("class", "bubble")
+121|        .attr("r", d => d.radius)
+122|        .attr("fill", d => SECTOR_COLORS[d.sector] || "#888");
+123|
+124|    node.append("text")
+125|        .attr("class", "bubble-label")
+126|        .attr("pointer-events", "none")
+127|        .text(d => d.ticker)
+128|        .style("font-size", d => Math.max(9, Math.min(14, d.radius * 0.5)) + "px");
+129|
+130|    const tooltip = d3.select("#tooltip");
+131|
+132|    node
+133|        .on("mouseover", function (event, d) {
+134|            if (d.isETF) return;
+135|            tooltip.classed("visible", true)
+136|                .html(
+137|                    `<div class="tt-ticker">${d.ticker}</div>` +
+138|                    `<div class="tt-name">${d.name}</div>` +
+139|                    `<div class="tt-sector" style="background:${SECTOR_COLORS[d.sector]}">${d.sector}</div>`
+140|                );
+141|        })
+142|        .on("mousemove", function (event, d) {
+143|            if (d.isETF) return;
+144|            tooltip
+145|                .style("left", (event.pageX + 14) + "px")
+146|                .style("top",  (event.pageY - 10) + "px");
+147|        })
+148|        .on("mouseout", function () {
+149|            tooltip.classed("visible", false);
+150|        })
+151|        .on("click", function (event, d) {
+152|            selectTicker(d.ticker);
+153|            event.stopPropagation();
+154|        });
+155|
+156|    // Click on empty SVG area clears selection.
+157|    svg.on("click", () => selectTicker(null));
+158|}
+159|
+160|// ---------------- Table ---------------- //
+161|
+162|function renderTable(stocks) {
+163|    const tbody = d3.select("#stock-table tbody");
+164|
+165|    const rows = tbody.selectAll("tr")
+166|        .data(stocks, d => d.ticker)
+167|        .join("tr")
+168|        .attr("data-ticker", d => d.ticker)
+169|        .on("click", function (event, d) {
+170|            selectTicker(d.ticker);
+171|            event.stopPropagation();
+172|        });
+173|
+174|    rows.append("td")
+175|        .attr("class", "ticker-cell")
+176|        .text(d => d.ticker);
+177|
+178|    rows.append("td")
+179|        .attr("class", "name-cell")
+180|        .text(d => d.name);
+181|
+182|    rows.append("td")
+183|        .append("span")
+184|        .attr("class", "sector-chip")
+185|        .style("background-color", d => SECTOR_COLORS[d.sector] || "#888")
+186|        .text(d => d.sector);
+187|
+188|    rows.append("td")
+189|        .attr("class", "num")
+190|        .text(d => formatMarketCap(d.marketCap));
+191|}
+192|
+193|// ---------------- Legend ---------------- //
+194|
+195|function renderLegend() {
+196|    const legend = d3.select("#legend");
+197|    SECTOR_ORDER.forEach(sector => {
+198|        const item = legend.append("div").attr("class", "legend-item");
+199|        item.append("span")
+200|            .attr("class", "legend-swatch")
+201|            .style("background-color", SECTOR_COLORS[sector]);
+202|        item.append("span").text(sector);
+203|    });
+204|}
+205|
+206|// ---------------- Linked selection ---------------- //
+207|
+208|let currentTicker = null;
+209|
+210|function selectTicker(ticker) {
+211|    currentTicker = (ticker === currentTicker) ? null : ticker;
+212|
+213|    d3.selectAll("#bubble-chart .bubble")
+214|        .classed("selected", d => currentTicker !== null && d.ticker === currentTicker);
+215|
+216|    d3.selectAll("#stock-table tbody tr")
+217|        .classed("selected", d => currentTicker !== null && d.ticker === currentTicker);
+218|
+219|    if (currentTicker) {
+220|        const row = document.querySelector(
+221|            `#stock-table tbody tr[data-ticker="${currentTicker}"]`
+222|        );
+223|        if (row) row.scrollIntoView({ block: "nearest", behavior: "smooth" });
+224|    }
+225|}
+226|
[end of edit 1 / 1]

